package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.PlantDao;import java.io.*;
@WebServlet("/admin/plants/form") public class AdminPlantFormServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{try{WebSupport.requireAdmin(r);PlantDao dao=new PlantDao();r.setAttribute("genera",dao.listGenera());String id=r.getParameter("id");if(id!=null){var p=dao.findById(Long.parseLong(id),true).orElseThrow();r.setAttribute("plant",p);r.setAttribute("aliases",dao.aliases(p.getId()));r.setAttribute("images",dao.images(p.getId()));}WebSupport.view(r,s,"admin/plant-form");}catch(Exception e){WebSupport.error(r,s,e,"无法打开植物录入表单。");}}}
